<script setup lang="ts">
import { computed,ref } from 'vue'
import { buscarDeuda, registrarPago } from '../services/pagos'
import type { Conexion } from '../interfaces/pagos.interface'
const query=ref(''),connection=ref<Conexion|null>(null),selected=ref<number[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref('')
const total=computed(()=>connection.value?.comprobantes.filter(x=>selected.value.includes(x.id)).reduce((n,x)=>n+Number(x.total),0)||0),all=computed(()=>!!connection.value?.comprobantes.length&&selected.value.length===connection.value.comprobantes.length)
const money=(n:number)=>Number(n).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2})
async function search(){if(!query.value.trim()){error.value='Ingrese el número del comprobante.';return}loading.value=true;error.value='';success.value='';try{connection.value=await buscarDeuda(query.value.trim());selected.value=connection.value.comprobantes.map(x=>x.id)}catch(e){connection.value=null;error.value=msg(e)}finally{loading.value=false}}
function toggleAll(){selected.value=all.value?[]:connection.value?.comprobantes.map(x=>x.id)||[]}async function pay(){if(!connection.value||!selected.value.length)return;if(!confirm(`¿Registrar el pago de S/ ${money(total.value)} por ${selected.value.length} comprobante(s)?`))return;saving.value=true;error.value='';try{const r=await registrarPago(connection.value.id,selected.value);success.value=`Pago registrado correctamente. Operación ${r.operacion} · ${r.fecha}`;connection.value=null;selected.value=[];query.value=''}catch(e){error.value=msg(e)}finally{saving.value=false}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Cobranza / Registro de pagos</nav><header class="hero"><div class="mark">S/</div><div><small>EVAN · COBRANZA</small><h1>Registro de pagos</h1><p>Consulta de deuda y recaudación de comprobantes pendientes.</p></div></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash error">{{error}}</p><form class="search" @submit.prevent="search"><div><small>BÚSQUEDA DE DEUDA</small><b>Ingrese el número del comprobante</b></div><input v-model.trim="query" placeholder="Número de comprobante" autofocus><button :disabled="loading">{{loading?'Buscando…':'Buscar deuda'}}</button></form><section v-if="connection" class="customer"><header><div><small>SUMINISTRO</small><h2>{{connection.suministro}}</h2><span :class="{off:connection.estado!=='Activo'}">{{connection.estado}}</span></div><strong>S/ {{money(connection.deuda)}}</strong><small>DEUDA CORRIENTE</small></header><dl><div><dt>Cliente</dt><dd>{{connection.cliente}}</dd></div><div><dt>Documento</dt><dd>{{connection.documento}}</dd></div><div><dt>Dirección</dt><dd>{{connection.direccion}}</dd></div><div><dt>Distrito</dt><dd>{{connection.distrito}}</dd></div></dl></section><section v-if="connection" class="receipts"><header><div><small>COMPROBANTES PENDIENTES</small><h2>Seleccione los documentos a recaudar</h2></div><label><input type="checkbox" :checked="all" @change="toggleAll"> Seleccionar todos</label></header><div v-if="!connection.comprobantes.length" class="empty">Esta conexión no presenta comprobantes pendientes de pago.</div><div v-else class="cards"><label v-for="x in connection.comprobantes" :key="x.id" :class="{selected:selected.includes(x.id)}"><input v-model="selected" type="checkbox" :value="x.id"><header><small>{{x.tipo}}</small><b>#{{x.numero||x.id}}</b></header><p>{{x.periodo||'Sin período'}}</p><dl><div><dt>Emisión</dt><dd>{{x.emision||'—'}}</dd></div><div><dt>Vencimiento</dt><dd>{{x.vencimiento||'—'}}</dd></div></dl><strong>S/ {{money(x.total)}}</strong></label></div><footer v-if="connection.comprobantes.length"><div><span>{{selected.length}} comprobantes seleccionados</span><b>Total a recaudar: S/ {{money(total)}}</b></div><button :disabled="saving||!selected.length" @click="pay">{{saving?'Registrando…':'Registrar pago'}}</button></footer></section><aside v-if="!connection&&!loading"><b>Recaudación segura</b><span>La búsqueda por comprobante identifica la conexión y recupera todos sus documentos pendientes.</span></aside></div></template>
<style scoped>
.page{--a:#22865f;color:#34444d}nav{margin-bottom:16px;color:#96a1a7;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:700}.hero small,.search small,.customer small,.receipts small{color:var(--a);font-size:.55rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7d898f;font-size:.65rem}.flash{padding:10px;font-size:.63rem}.good{color:#287258;background:#edf9f3}.error{color:#a13f43;background:#fff0f0}.search{margin-top:13px;padding:16px;display:grid;grid-template-columns:1.2fr 2fr auto;align-items:end;gap:10px;border-radius:9px;background:#fff}.search small,.search b{display:block;font-size:.55rem}.search input{padding:10px;border:1px solid #d8e0e4;border-radius:6px;font:inherit;font-size:.6rem}.search button,.receipts>footer button{padding:10px 14px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.56rem}.customer{margin-top:12px;display:grid;grid-template-columns:230px 1fr;border-radius:9px;background:#fff;overflow:hidden}.customer>header{padding:17px;color:#fff;background:var(--a)}.customer>header small{color:#c9f0e1}.customer h2{margin:3px 0;font-size:1rem}.customer header span{padding:3px 6px;border-radius:8px;background:#ffffff33;font-size:.46rem}.customer header strong{margin-top:14px;display:block;font-size:1.1rem}.customer dl{padding:12px 18px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.customer dt{color:#89949a;font-size:.47rem}.customer dd{margin:3px 0;font-size:.56rem;font-weight:700}.receipts{margin-top:12px;border-radius:9px;background:#fff}.receipts>header{padding:14px 16px;display:flex;justify-content:space-between;border-bottom:1px solid #e8edef}.receipts h2{margin:3px 0;font-size:.68rem}.receipts>header label{font-size:.51rem}.cards{padding:12px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.cards>label{padding:12px;border:1px solid #dfe5e7;border-radius:7px;font-size:.5rem}.cards>label.selected{border-color:var(--a);background:#edf9f3}.cards>label>input{float:right}.cards header small,.cards header b{display:block}.cards header b{font-size:.62rem}.cards>label>p{color:#849096}.cards dl{display:grid;grid-template-columns:1fr 1fr}.cards dt{color:#89949a;font-size:.43rem}.cards dd{margin:2px 0}.cards>label>strong{margin-top:8px;display:block;color:var(--a);font-size:.68rem}.receipts>footer{padding:14px 16px;display:flex;justify-content:flex-end;align-items:center;gap:16px;border-top:1px solid #e8edef}.receipts>footer span,.receipts>footer b{display:block;text-align:right;font-size:.53rem}.empty{padding:35px;text-align:center;font-size:.58rem}aside{margin-top:12px;padding:20px;display:flex;flex-direction:column;align-items:center;color:#78858b;background:#fff;font-size:.56rem}@media(max-width:850px){.cards{grid-template-columns:1fr 1fr}.search{grid-template-columns:1fr}.customer{grid-template-columns:1fr}}@media(max-width:500px){.cards,.customer dl{grid-template-columns:1fr}.receipts>footer{align-items:stretch;flex-direction:column}.receipts>footer span,.receipts>footer b{text-align:left}}
</style>
